.elementor-widget-wrap>.elementor-element{width:100%}
.elementor-widget{position:relative}
.elementor-widget:not(:last-child){margin-bottom:20px}
.elementor-column{position:relative;min-height:1px;display:flex}
.elementor-column-gap-default>.elementor-row>.elementor-column>.elementor-element-populated{padding:10px}
@media (min-width:768px){.elementor-column.elementor-col-33{width:33.333%}.elementor-column.elementor-col-66{width:66.666%}.elementor-column.elementor-col-100{width:100%}}
@media (max-width:767px){.elementor-column{width:100%}}
.elementor-element .elementor-widget-container{transition:background 0.3s,border 0.3s,border-radius 0.3s,box-shadow 0.3s,-webkit-border-radius 0.3s,-webkit-box-shadow 0.3s}
.elementor-accordion .elementor-tab-content{display:none;padding:15px 20px;border-top:1px solid rgb(212,212,212)}
@media (max-width:767px){.elementor-accordion .elementor-tab-content{padding:7px 15px}}
.elementor-widget-heading .elementor-heading-title{padding:0px;margin:0px;line-height:1}
.elementor-widget-heading .elementor-heading-title>a{color:inherit;font-size:inherit}
.elementor-widget-image{text-align:center}
.elementor-widget-image .elementor-image img{vertical-align:middle;display:inline-block}
.elementor-widget-text-editor p,.elementor-accordion .elementor-tab-content p{float:left;width:100%}
.fa-check::before{content:""}
.mm_columns_ul{animation-duration:0.5s;animation-fill-mode:both}
